import sys
sys.path.insert(0, '/home/user/cautious-chainsaw/tmp/fence-3/scripts')
from rowlib import Row
from cite import OR, SV, LIB, WEB, NPSW

WIKI = 'Wikipedia (not an admissible source, Law cl.4)'


def S080():
    R = Row('S-080')
    c1 = R.cite(LIB('CEM-REPORT-1867', 'I accordingly appointed David Wills, Esq., of Gettysburg, my agent, and through him, a site was purchased at a cost of $2,475 87, and the conveyances made to the Commonwealth.', title="Report of the Select Committee relative to the Soldiers' National Cemetery (1865, revised 1867): the Governor's statement", note='Printed in the volume as a message of the Governor of Pennsylvania; the volume prints it twice with the same wording (also in the Indiana edition and in Everett\'s oration volume of 1864).'))
    c2 = R.cite(LIB('CEM-REPORT-1867', 'Two lots were bought at the rate of $225 per acre ; one for $200 per acre; one for $150 per acre, and one for $135 per acre. The whole embraces about seventeen acres', title="Report of the Select Committee relative to the Soldiers' National Cemetery (1865, revised 1867): Wills's report of 21 Mar 1864", note='Wills: "after much difficulty, succeeded in buying five different lots lying on Cemetery Hill".'))
    c3 = R.cite(LIB('NPS-ADHI', "Evergreen Cemetery Association reluctantly agreed on August 14 to sell Wills twelve acres of the Cemetery Hill lands adjoining the civilian cemetery for the exclusive use of the soldiers' cemetery for $2,475.87.", title='NPS, H. D. Unrau, Administrative History: Gettysburg National Military Park and National Cemetery (1991), pdf p.22', note='Secondary: citing the McConaughy, Wills and Curtin correspondence of July-August 1863.'))
    c4 = R.cite(LIB('NPS-ADHI', 'A day or two later Wills bought an additional five acres adjoining the larger tract of twelve acres', title='NPS, H. D. Unrau, Administrative History (1991), pdf p.22'))
    c5 = R.cite(NPSW('tribune_1121_p2', 'and sowe seventeen acres of land were purchased for the som of £3,150', note='New-York Daily Tribune, 21 Nov 1863, letter of a special correspondent dated Gettysburg, 17 Nov 1863. OCR "sowe" for some and "som" for sum; the currency sign is read as "£" by the OCR (an American newspaper pricing a Pennsylvania purchase: probably the dollar sign).'))
    R.sub('seventeen_acres_bought_through_wills', 'About seventeen acres on Cemetery Hill were bought through David Wills, the Governor\'s agent, in five lots at $135 to $225 an acre (Wills, 21 Mar 1864); NPS dates the first twelve acres to 14 Aug 1863 and five more acres to a day or two later.', 'documented', [c2, c1, c3, c4],
          why='Wills\'s own report and the Governor\'s statement; the August dates are NPS\'s (secondary). "Five lots" (Wills) and "five additional acres" (NPS) are different counts.')
    R.sub('the_2475_87_is_the_price_of_twelve_acres_not_of_seventeen', 'The sum of $2,475.87 is the cost of "a site" in the Governor\'s statement and, in NPS\'s account, the price of the twelve acres sold on 14 Aug 1863 by the Evergreen Cemetery Association; the five further acres were bought a day or two later at an unstated price.', 'documented', [c1, c3, c4],
          why='The printed row ("17 acres bought by Wills for about $2,475.87") joins two figures: the total price of the seventeen acres is given in no official local text (a newspaper gives $3,150, below).')
    R.sub('contemporary_newspaper_total_price_3150', 'A New-York Tribune correspondent writing from Gettysburg on 17 Nov 1863 says that "some seventeen acres of land were purchased for the sum of $3,150" (the OCR prints a pound sign before 3,150), a total price that no official local text states.', 'documented', [c5], support='partial',
          why='A correspondent\'s statement printed 21 Nov 1863, not Wills\'s own account; the currency sign is garbled in the OCR. It is a different figure from $2,475.87 and agrees with NPS that $2,475.87 was the price of the first twelve acres only.')
    R.sub('late_july_and_august_1863', 'The negotiations ran from late July (McConaughy to Curtin, 25 Jul) to the sale of 14 Aug and Wills\'s report to Curtin on 17 Aug 1863; the purchases by Wills themselves are of August.', 'documented', [c3], support='partial',
          why='NPS footnotes list the letters of 25 and 29 Jul and 5 and 14 Aug (McConaughy) and 3, 7, 10 and 11 Aug (Wills); the letters themselves are not local.')
    R.lookup('Soldiers\' National Cemetery reports (1864, 1865, 1867), Bartlett 1874, NPS administrative history, CLR: acres and price', 'ws9, NPS texts', 'quotes above', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov text service): Evening Star 19-21 Nov 1863 and New-York Daily Tribune 20-21 Nov 1863, price of the ground', 'web (reachable hosts), paced one request per second', 'Tribune 21 Nov 1863 p.2: seventeen acres for $3,150 (OCR sign garbled); the Star pages give no price', 'done')
    R.unsupported('The total cost of the seventeen acres; the sources W-CONS (Wikipedia) and GC-COMP (a blog, not admissible).')
    return R.finish('corrected', 'open',
        'The soldiers\' cemetery ground is about seventeen acres on Cemetery Hill bought through David Wills in five lots (Wills, 21 Mar 1864): the first twelve acres were sold by the Evergreen Cemetery Association on 14 Aug 1863 and five more a day or two later (NPS), after negotiations from late July; $2,475.87 is the cost of the site per the Governor\'s statement and the price of the twelve acres per NPS; the total price of the seventeen acres is not stated in any official text; a New-York Tribune correspondent of 17 Nov 1863 puts it at $3,150 (OCR sign garbled).',
        register=['fence-3-EG-16'],
        product=['State schedule S-080 / WS-080-land: area 17 acres (documented); price: do not print "$2,475.87 for 17 acres" - print "$2,475.87 for the twelve acres sold on 14 Aug 1863"; the total for the seventeen acres only as a newspaper figure (about $3,150, New-York Tribune, 21 Nov 1863), the official total open; date range late July to August 1863.'],
        changes=['The row printed no source check; Curtin/Wills (1864-65 volumes) and NPS now date and split the purchase.', 'A contemporary newspaper (New-York Daily Tribune, 21 Nov 1863, read from the Library of Congress text service) gives about $3,150 for the seventeen acres.'])


def S081():
    R = Row('S-081')
    w1 = R.cite(LIB('CEM-REPORT-1867', 'The contractor commenced the work of exhuming on Tuesday, the 27th of October last, and finished yesterday.', nth=0, title="Report of the Select Committee relative to the Soldiers' National Cemetery (1865, revised 1867): report of Samuel Weaver, superintendent of the exhuming", note='Printed twice in the volume (offsets 215862 and 218700); the first is cited.'))
    w2 = R.cite(LIB('CEM-REPORT-1867', 'makes the total number of removals thirty-five hundred and twelve (3,512) bodies', title="Report of the Select Committee (1867): Weaver's report", note='Context: the Massachusetts removals "taken up by the authorities of the city of Boston, by special contract, amounting to one hundred and fifty-eight" are included; "nine hundred and seventy-nine were bodies nameless".'))
    n1 = R.cite(LIB('NPS-CLR-CEMETERY', 'The first reinterment in the national cemetery, of a soldier removed from Gettysburg\'s Presbyterian graveyard, occurred around October 17.', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.69'))
    n2 = R.cite(LIB('NPS-CLR-CEMETERY', 'Prior to the Biesecker contract that began on October 27 1863', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.69', note='Sentence continues "others began work on disinterring Union remains from local cemeteries."'))
    n3 = R.cite(LIB('NPS-CLR-CEMETERY', 'approximately 1,200 graves, or roughly a third of', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.70', note='The text layer interleaves two columns; the passage reads "there were five complete and three incomplete state plots on the right (east) of the cemetery, containing approximately 1,200 graves, or roughly a third of the anticipated reinterments" (at the dedication).'))
    n4 = R.cite(LIB('NPS-CLR-CEMETERY', 'Reinterment of the total 3,512 bodies was completed', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.70', note='Continues in the other column with "on March 18, 1864." (quoted separately).'))
    n5 = R.cite(LIB('NPS-CLR-CEMETERY', 'on March 18, 1864. The largest state plots were New', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.70'))
    t_head = R.cite(NPSW('tribune_1121_p2', 'The following is a list of the remains already interred In the Cemetery, with the States they represent', note='New-York Daily Tribune, 21 Nov 1863, end of the letter of a special correspondent dated Gettysburg, 19 Nov 1863 (the heading of the list is "THE PATRIOT REMAINS").'))
    t_src = R.cite(NPSW('tribune_1121_p2', 'Mr. Townsend of Rahway, N. J, who ls ths Buperin. tendent of the grounds', note='OCR "ls ths Buperin. tendent" for is the Superintendent; the sentence reads "adding here the list of dead already buried in the Cemetery, which I obtained through the kindness of Mr. Townsend of Rahway, N. J., who is the Superintendent of the grounds, I close this already long letter".'))
    t_total = R.cite(NPSW('tribune_1121_p2', 'Totbesssivnssnnsnseressh 188', note='OCR of the last line of the table ("Total ... 1,188"): the OCR drops the digit 1, the comma and the dot leaders. The page image (region saved at tmp/fence-3/web/chronam/tribune_1863-11-21_sp2_remains_table.jpg, viewed 2026-11-13) reads "Total ...1,188", with the sub-totals 606 (by State) and 582 (Unknown), which add to 1,188.'))
    ty = R.cite(LIB('NPS-CEM-DEDICATION', 'At that tine. 1,188 bodies', title='NPS typescript on the circumstances of the dedication (pdf p.32)', note='OCR of a typescript: "Soldier dead from the battlefield were being reburied in the several State plots indicated at the time of the dedication service, November 19, 1863. At that time 1,188 bodies had been reinterred." (OCR "tine", "had-been re». interred").'))
    R.sub('contractor_started_27_oct_1863', 'The contractor\'s exhuming of the battlefield graves began on Tuesday, 27 Oct 1863.', 'documented', [w1, n2],
          why='Weaver, the superintendent (primary, printed in the 1865-67 reports); NPS CLR (Biesecker contract).')
    R.sub('first_reinterment_about_17_oct', 'The first reinterment in the national cemetery, of a soldier from Gettysburg\'s Presbyterian graveyard, occurred around 17 Oct.', 'documented', [n1],
          why='Resolves the plan\'s "Oct 17 or Oct 27" (conflict in the timeline tail): 17 Oct is the first reinterment from a local graveyard, 27 Oct the start of the contractor\'s battlefield work; both are documented and compatible.')
    R.sub('total_3512', 'In all 3,512 Union bodies were removed (979 unidentified by name or State), the Massachusetts removals (158) included.', 'documented', [w2, n4],
          why='Weaver and the CLR.')
    R.sub('tribune_list_total_1188_on_19_nov', 'The New-York Daily Tribune of 21 Nov 1863 prints, at the end of a correspondent\'s letter dated 19 Nov and with the figures obtained from the superintendent of the grounds, "a list of the remains already interred in the Cemetery, with the States they represent", totalling 1,188 (the States 606, unknown 582); an NPS typescript says that at the dedication "1,188 bodies had been reinterred".', 'documented', [t_head, t_src, t_total, ty],
          why='A contemporary count by the superintendent of the grounds, printed two days after the dedication; the total is read from the page image (the OCR keeps only "188") and agrees with the NPS typescript. The CLR\'s "approximately 1,200 graves" is the same order.')
    R.sub('about_1200_graves_clr', 'The NPS CLR says that at the dedication five complete and three incomplete State plots held approximately 1,200 graves, roughly a third of the anticipated reinterments.', 'documented', [n3], support='partial',
          why='Rounded figure of a secondary source; it agrees with the superintendent\'s 1,188.')
    R.sub('by_19_nov_1258', '1,258 had been reburied by 19 Nov (printed).', 'open_gap', [], support='none',
          why='No text gives 1,258: the superintendent\'s list printed in the Tribune (1,188), the NPS typescript (1,188) and the CLR (about 1,200) all differ from it.')
    R.sub('completed_18_mar_1864', 'The work, interrupted when the ground froze, was completed on 18 Mar 1864 (printed "due to finish March 1864").', 'documented', [n5, n4, w1],
          why='CLR; Weaver\'s report ("The work has been protracted much beyond our original anticipations, by reason of the ground being frozen for a long time during the winter").')
    R.lookup('Select Committee reports, Bartlett 1874, NPS CLR, NPS dedication typescript: reburial dates and counts', 'ws9, NPS texts', 'quotes above', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov text and image services): New-York Daily Tribune 21 Nov 1863 p.2, the list of remains interred; page image region viewed', 'web (reachable hosts), paced one request per second', 'total 1,188 (606 by State, 582 unknown), figures from the superintendent of the grounds', 'done')
    R.unsupported('The count 1,258 on 19 Nov (no text; the Tribune list, the NPS typescript and the CLR give other numbers).')
    return R.finish('corrected', 'closed',
        'Reburial: the first reinterment in the national cemetery was about 17 Oct (from a local graveyard), the contractor began on the battlefield on Tuesday 27 Oct 1863, and the work was completed on 18 Mar 1864 after a winter stop; 3,512 Union bodies in all. On 19 Nov the superintendent\'s list printed in the New-York Tribune of 21 Nov 1863 gives 1,188 remains interred (606 by State, 582 unknown); the NPS typescript agrees and the CLR says about 1,200 graves; 1,258 is not found.',
        register=[],
        product=['State schedule S-081 / WS-081-reburials: both start dates are one event each (17 Oct first reinterment; 27 Oct contractor), so the "start_oct17 / start_oct27" scenarios can be merged into two sequential facts; count on 19 Nov: 1,188 (the superintendent\'s list, New-York Tribune 21 Nov 1863; the NPS typescript agrees; the CLR\'s about 1,200 is the same order); the printed 1,258 stays visible as unsupported; completion 18 Mar 1864.'],
        changes=['The printed conflict Oct 17 versus Oct 27 is dissolved by the CLR; the number 1,258 is not supported and is contradicted by a contemporary list and the NPS typescript (both 1,188).'])


def S082():
    R = Row('S-082')
    a1 = R.cite(LIB('NPS-ADHI', 'an open iron railing enclosure of ordinary height be made and maintained by the State, or states interested, upon the division lines between said lands, and the grounds of Ever-Green Cemetery.', title='NPS, H. D. Unrau, Administrative History (1991), pdf p.22', note='The Evergreen Cemetery Association\'s stipulation in the sale to Wills of 14 Aug 1863, quoted by NPS from the correspondence; also in the 2017 CLR.'))
    a2 = R.cite(LIB('NPS-CLI-CEMETERY', 'was organized around a central open space formed by the semi-circular burial grounds', title='NPS Cultural Landscapes Inventory: Gettysburg National Cemetery (2019), pdf p.29'))
    a3 = R.cite(LIB('NPS-CLI-CEMETERY', 'Saunders designed an open enclosure along the boundary consisting of a low pipe-rail fence and hedge', title='NPS Cultural Landscapes Inventory: Gettysburg National Cemetery (2019), pdf p.24', note='Sentence continues "in contrast to the massive stone wall and ornate iron fence that were used on the outer boundaries."'))
    a4 = R.cite(LIB('NPS-CLI-CEMETERY', 'The Evergreen Cemetery boundary fence, which extended 1,450 feet from Baltimore Street to the south end of the cemetery, was a simple three-foot-tall iron fence behind a hedge of arborvitae', title='NPS Cultural Landscapes Inventory: Gettysburg National Cemetery (2019), pdf p.36', note='Historic condition 1863-1928.'))
    a5 = R.cite(LIB('NPS-CLI-CEMETERY', 'replacement of the pipe-rail fence and hedge along the Evergreen Cemetery boundary with a seven-foot-tall ornate iron fence', title='NPS Cultural Landscapes Inventory: Gettysburg National Cemetery (2019), pdf p.25', note='The 1935 work.'))
    a6 = R.cite(LIB('CEM-BARTLETT-1874', 'simply a low iron fence', title="J. R. Bartlett (ed.), The Soldiers' National Cemetery at Gettysburg (1874)", note='Sentence: "The division line between the soldiers\' and the local cemetery is simply a low iron fence, the remainder being enclosed by a substantial stone wall"; describes the finished cemetery.'))
    a7 = R.cite(LIB('NPS-CLI-CEMETERY', 'On November 19, 1863, President Abraham Lincoln dedicated the unfinished national cemetery', title='NPS Cultural Landscapes Inventory: Gettysburg National Cemetery (2019), pdf p.24'))
    a8 = R.cite(NPSW('snm', 'a short distance on the other side of the iron fence and inside the Evergreen Cemetery', note='Present-tense NPS wording; the page does not say the fence existed in 1863.'))
    a10 = R.cite(LIB('NPS-CLR-CEMETERY', 'President Lincoln asked William Saunders to come to his office on November 17 to show him his plan for the cemetery', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.71', note='So Saunders\'s plan existed on 17 Nov 1863; the CLR (pdf p.64) says he "settled on a plan in which all the remains would be laid out in a single group, forming a semi-circle around a central" monument (the sentence is interleaved with another column in the text layer).'))
    a9 = R.cite(LIB('NPS-CLR-CEMETERY', 'was outfitted with a temporary white', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.39', note='Sentence (interleaved with a caption in the text layer): "The road frontage of the cemetery was outfitted with a temporary white-painted wood plank fence and entrance gate, in place of the \'tasteful front enclosure\'-an ornate iron fence and gate-that the cemetery association hoped to erect"; this is the Evergreen Cemetery\'s own frontage before the battle.'))
    tl1 = R.cite(NPSW('tribune_1121_p2', 'half circles around a common oeuter, on which it is proposed to erect a monument', note='New-York Daily Tribune, 21 Nov 1863, letter of a special correspondent dated Gettysburg, 19 Nov 1863 (written on the morning of the dedication). OCR "oeuter" for center; the sentence begins "The side of the hill is [laid] out" (OCR "Ing out").'))
    tl3 = R.cite(NPSW('tribune_1121_p2', 'William Saunders, o landscape gardner, of Wash. ngton', note='OCR for "William Saunders, a landscape gardener, of Washington"; the sentence begins "This simple but appropriate plan was designed by".'))
    tl2 = R.cite(NPSW('tribune_1121_p2', 'will be surroubded by a subetautial stone', note='OCR for "will be surrounded by a substantial stone"; the last word is cut off in the OCR ("w", presumably wall). Future tense: the enclosure of the whole grounds was still to come on 19 Nov.'))
    R.sub('semicircular_plots_saunders_design', 'The soldiers\' cemetery was laid out in semicircular burial plots to William Saunders\'s design; his plan existed on 17 Nov 1863 and the cemetery was "unfinished" on 19 Nov.', 'documented', [a10, a2, a7], why='NPS CLR and inventory; the completed landscape is of 1869.')
    R.sub('newspaper_of_19_nov_semicircles_and_future_stone_enclosure', 'A New-York Tribune correspondent on the ground on the morning of 19 Nov 1863 describes the hillside as laid out "in half circles around a common center" where a monument is proposed, the plan designed by William Saunders, a landscape gardener of Washington (OCR "o landscape gardner, of Wash. ngton"), and says that the grounds as a whole "will be surrounded by a substantial stone" [wall] (future tense; the last word is cut off in the OCR); the legible parts of his description mention no iron fence between the soldiers\' ground and Evergreen.', 'documented', [tl1, tl3, tl2], support='partial',
          why='A contemporary eyewitness on the day. Part of the passage is lost in the OCR ("Avennes portions of the unds"), so the absence of a fence in his text is not proof; the stone enclosure of the whole grounds is future (Bartlett 1874 describes the finished cemetery with a stone wall and a low iron fence on the Evergreen line).')
    R.sub('iron_railing_stipulated_14_aug_1863', 'The Evergreen Cemetery Association made "an open iron railing enclosure of ordinary height ... upon the division lines" a condition of the sale of 14 Aug 1863.', 'documented', [a1], why='A stipulation, not a fence: it does not say when the railing was put up.')
    R.sub('built_form_conflict', 'The boundary fence as built is described three ways: a low pipe-rail fence and hedge (Saunders design, NPS 2017/2019), a three-foot-tall iron fence behind an arborvitae hedge (NPS 2019, 1863-1928), "simply a low iron fence" (Bartlett 1874); the seven-foot ornate iron fence is of 1935.', 'documented', [a3, a4, a6, a5],
          why='Three descriptions of the same line; none dated before 1864. Carried as selectable scenarios (no default).')
    R.sub('iron_fence_existed_on_19_nov_1863', 'An iron fence separated the new cemetery from Evergreen Cemetery on 19 Nov 1863 (printed).', 'open_gap', [a7, a8], support='none',
          why='Nothing local says the fence was built by the dedication: the CLI calls the cemetery "unfinished" on 19 Nov; the NPS web page uses "the iron fence" in the present tense; Evergreen\'s own frontage had a temporary wood plank fence in 1863 (CLR). A Tribune correspondent on the ground that morning writes of a stone enclosure still to come and mentions no iron fence in the legible text of his description. The plan\'s W-CONS is Wikipedia (not admissible).')
    R.lookup('NPS administrative history, CLR, CLI, Bartlett 1874: the dividing fence and its date', 'NPS texts, ws9', 'stipulation of 14 Aug 1863; built forms; no completion date', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov): Evening Star 19-21 Nov 1863, New-York Daily Tribune 20-21 Nov 1863: the boundary between the cemeteries', 'web (reachable hosts)', 'the Tribune letter of 19 Nov describes half circles and a stone enclosure to come; no text names an iron fence', 'done')
    R.lookup('NPS-CEM-ENCLOSURES (the 1980s study of the cemetery enclosures)', 'NPS text', 'text layer scrambled (columns interleaved): cannot be quoted reliably; the study\'s statements on the date of the dividing fence are owed (page images)', 'failed')
    R.unsupported('That an iron fence stood on 19 Nov 1863 (the plan\'s W-CONS, Wikipedia).')
    return R.finish('corrected', 'open',
        'The soldiers\' cemetery was laid out in semicircular plots to Saunders\'s design; the Evergreen Cemetery Association made an open iron railing on the division line a condition of the sale of 14 Aug 1863 (NPS, quoting the agreement), but the fence as built is described as a low pipe-rail fence with a hedge, a three-foot iron fence behind arborvitae or a low iron fence, and nothing local shows any of them standing on 19 Nov 1863, when the cemetery was "unfinished"; a New-York Tribune correspondent on the ground that morning describes half circles round a common center, Saunders\'s plan and a stone enclosure still to come, and mentions no iron fence.',
        register=['fence-3-EG-17'],
        product=['State schedule S-082 / WS-082-layout: keep the semicircle (documented); the boundary fence on 19 Nov 1863 becomes an open-gap state with three selectable forms (none by default): open iron railing (stipulated), low pipe-rail fence and hedge, low iron fence; no iron fence in the dedication scene until a source dates it. Evergreen\'s frontage fence in 1863: temporary white-painted wood plank fence (CLR). The stone enclosure of the whole grounds is future on 19 Nov (Tribune, 21 Nov 1863): do not draw a stone wall as built.'],
        changes=['The row said "iron fence"; the 1863 stipulation is documented but the existence on 19 Nov is not, and the built form is disputed within NPS.', 'The shard\'s NPS web quotation is now matched (offset in the citation) and its present-tense wording noted.'])


def S083():
    R = Row('S-083')
    p1 = R.cite(LIB('NPS-CLR-CEMETERY', 'The flagstaff is roughly on the border between the two cemeteries; to the left within Evergreen Cemetery is the grandstand.', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.71, caption of Figure 1.40 (Joseph Becker sketch, circa 18 Nov 1863)'))
    p2 = R.cite(LIB('NPS-CLI-CEMETERY', "Lincoln gave his Gettysburg Address from speaker's stand in Evergreen Cemetery", title='NPS Cultural Landscapes Inventory: Gettysburg National Cemetery (2019), pdf p.16', note='Sentence: "In his dedication of Soldiers\' National Cemetery on November 19, 1863, President Lincoln gave his Gettysburg Address from speaker\'s stand in Evergreen Cemetery."'))
    p3 = R.cite(NPSW('snc_article', 'a special platform had been constructed at the edge of the new cemetery'))
    p4 = R.cite(NPSW('snm', 'a short distance on the other side of the iron fence and inside the Evergreen Cemetery', note='Present-tense NPS wording.'))
    p5 = R.cite(LIB('NPS-CEM-DEDICATION', 'platform Stood at tho time o f the dedication', title='NPS typescript on the circumstances of the dedication (pdf p.30, caption)', note='OCR of a typescript caption: "The monument is located at the place where the platform stood at the time of the dedication."'))
    p6 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'the stand erected in the centre of the same was aurfmnded by at least twenty thousand citizens', title='Adams Sentinel, 24 Nov 1863: account of the dedication ("Soldiers\' National Cemetery")', note='OCR "aurfmnded" for surrounded; "the same" is the cemetery grounds.'))
    st1 = R.cite(NPSW('star_1120_p2', 'in the centre of the cemetery a quarter before noon', note='Evening Star (Washington), 20 Nov 1863: "The head of the procession reached the platform erected in the centre of the cemetery a quarter before noon"; the OCR garbles the preceding words ("plat rm erccte<|"). The New-York Tribune dispatch of the same day has the head of the procession at "the main stand" at a quarter past 11.'))
    tl4 = R.cite(NPSW('tribune_1121_p2', 'the military formed around the inadequately sized platform', note='New-York Daily Tribune, 21 Nov 1863, letter of a special correspondent dated Gettysburg, 19 Nov 1863.'))
    R.sub('platform_built_by_19_nov_1863', 'The speaker\'s stand was built before the dedication: the Becker sketch of about 18 Nov shows the grandstand next to the flagstaff, and the procession reached "a special platform" on 19 Nov.', 'documented', [p1, p3], why='NPS CLR and NPS article.')
    R.sub('evergreen_side_scenario', 'The platform stood on the Evergreen Cemetery side of the boundary near the flagstaff (NPS CLR 2017, CLI 2019, the web page).', 'documented', [p1, p2, p4],
          why='Matches the plan\'s "Wills (1992) and Frassanito (1995)" reading, which are not local. The boundary fence is not shown in any local text for that date (S-082).')
    R.sub('monument_site_scenario', 'The platform stood at the later monument site, "in the centre" of the cemetery grounds (the Adams Sentinel; the Evening Star of 20 Nov 1863 has the head of the procession reach the platform "in the centre of the cemetery").', 'documented', [p5, p6, st1],
          why='The older park typescript and two contemporary newspaper accounts place it so; this is the "earlier park materials" scenario of the plan. "The cemetery" in the newspapers is the new soldiers\' ground; whether the stand lay on the Evergreen side of the boundary is not said.')
    R.sub('platform_called_inadequately_sized', 'A New-York Tribune correspondent calls it "the inadequately sized platform" (the military formed round it and the guests took their places on it).', 'documented', [tl4], support='partial',
          why='A qualitative statement, not a dimension.')
    R.sub('straddling_scenario', 'The platform straddled the Evergreen and Soldiers\' National cemeteries and Lincoln stood well within the Soldiers\' National (Library of Congress blog, 2023).', 'open_gap', [], support='none',
          why='Reported by a search summary of https://blogs.loc.gov/loc/2023/11/where-did-lincoln-stand-while-delivering-the-gettysburg-address/ (the host answered 403 on CONNECT on 2026-11-13); not read, not cited.')
    R.sub('platform_footprint_height_rail', 'Footprint, height and rail of the platform.', 'open_gap', [], support='none', why='No local text gives a dimension (a Tribune correspondent calls the platform "inadequately sized"); the NPS typescript mentions two platforms facing each other in a photograph (a different date, 1865).')
    R.lookup('NPS CLR/CLI, NPS articles, the dedication typescript, the Sentinel of 24 Nov 1863: where the stand stood', 'NPS texts and pages, ws9', 'three placements: Evergreen side, monument site, "centre of the grounds"; one more (straddling) unread', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov): Evening Star 20 Nov 1863 and New-York Daily Tribune 20-21 Nov 1863: the platform', 'web (reachable hosts)', 'Star: platform in the centre of the cemetery; Tribune: the main stand, the inadequately sized platform; no boundary named', 'done')
    R.unsupported('Wills (1992) and Frassanito (1995) (print sources, not local); footprint, height and rail.')
    return R.finish('corrected', 'blocked_host',
        'The speaker\'s stand was built by 18-19 Nov 1863 near the flagstaff on the border of the two cemeteries (Becker sketch, NPS CLR): NPS places it on the Evergreen side (CLR 2017, CLI 2019, web page), an older NPS typescript and the Sentinel of 24 Nov 1863 put it at the later monument site or in the centre of the grounds, and a 2023 Library of Congress blog (unread) says it straddled the boundary; the Evening Star of 20 Nov 1863 has the procession reach the platform in the centre of the cemetery and a Tribune correspondent calls it inadequately sized. All placements stay selectable; none is chosen.',
        register=['fence-3-EG-17'],
        blocked_host=[{'url': 'https://blogs.loc.gov/loc/2023/11/where-did-lincoln-stand-while-delivering-the-gettysburg-address/', 'what_to_read': 'The Library of Congress blog "160 Years Later ... Where Did Lincoln Stand While Delivering the Gettysburg Address?": the argument that the speaker\'s platform straddled Evergreen and Soldiers\' National cemeteries, its evidence (six photographs) and any statement about a dividing fence. The host answered 403 on CONNECT when probed once on 2026-11-13.'},
                      {'url': 'Garry Wills, Lincoln at Gettysburg (1992); William Frassanito, Early Photography at Gettysburg (1995)', 'what_to_read': 'The platform placement relative to the dividing fence (keys in the plan: W-CONS). Print sources, owner-only to acquire.'}],
        product=['State schedule S-083 / WS-083-platform: three selectable placements (Evergreen side near the flagstaff; later monument site, the "centre" of the cemetery in the Sentinel and the Evening Star; straddling the boundary), no default; the platform drawn small ("the inadequately sized platform", Tribune; no dimension found); the platform stood by 18 Nov (Becker sketch); no dividing fence to be drawn beside it until a source dates one (S-082).'],
        changes=['The shard could not read any of these; two NPS documents, a typescript and a newspaper now document three placements.'])


def S084():
    R = Row('S-084')
    s1 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'dimly seen through tbo November mists', title='Adams Sentinel, 24 Nov 1863: account of the dedication', note='Sentence: "Standing upon the platform, the whole battlefield lay spread out like a panorama before the beholder. In the distance the surrounding hills where, on the memorable days of July, stood the Rebel invaders, dimly seen through the November mists, on either hand and beneath us the very heights so heroically defended"; OCR "tbo".'))
    t1 = R.cite(LIB('TPIERCE-1889', 'Fences had disappeared, some buildings wTre gone, others ruined.', title='Tillie Pierce Alleman, At Gettysburg (1889), chapter VI, printed page 82', note='Of 7 Jul 1863, fields south of the town; OCR "wTre" for "were".'))
    c1 = R.cite(LIB('NPS-CLR-CEMETERY', 'was outfitted with a temporary white', title='NPS Cultural Landscape Report: Gettysburg National Cemetery (2017), pdf p.39', note='Evergreen Cemetery\'s own road frontage before the battle: "a temporary white-painted wood plank fence and entrance gate".'))
    r1 = R.cite(NPSW('tribune_1121_p2', 'Rifle-pits line the whole length of the road', note='New-York Daily Tribune, 21 Nov 1863, letter of a special correspondent dated Gettysburg, 17 Nov 1863: driving out from the town on the Emmitsburg road toward Round Top ("This was the road upon which our army entered the town"); the sentence before says the road "bears the same marks and evidences of the bloody struggle ... as have been described on the Chambersburg road, but to a much greater extent".'))
    r2 = R.cite(NPSW('tribune_1121_p2', 'knapsacks, canteens, cups, bayonets, cartridge boxes, shoes, stockings, remnants of coats sud vests', note='Same letter and road; OCR \"sud\" for and. The sentence continues: \"and numberless caps and belts are scattered in great profusion through the fields and woods and along the road\".'))
    r3 = R.cite(NPSW('tribune_1121_p2', 'Wood: en fences are torn down and the stone ones strength. ened and nsed as hreastworks', note='Same letter and road; OCR \"Wood: en\" for Wooden, \"strength. ened\" for strengthened, \"nsed as hreastworks\" for used as breastworks.'))
    r4 = R.cite(NPSW('tribune_1121_p2', 'Trees marked, limbs and brauches torn', note='Same letter: \"Through the woods we found unmistakable signs of the severity of the contest\", on the drive from Lee\'s headquarters toward the grove where the fighting began on 1 Jul (the field of the first day); OCR \"brauches\" for branches. The sentence continues \"breastworks and rifle-pits before and around us, the houses in the neighborhood scarred and torn in various ways\" (OCR garbled).'))
    R.sub('distant_hills_dimly_seen_in_mist', 'On 19 Nov the hills where the Confederates stood in July were "dimly seen through the November mists"; the whole battlefield lay spread out below the stand.', 'documented', [s1],
          why='Contemporary newspaper (24 Nov 1863). It does not name the Blue Ridge.')
    R.sub('fences_gone_from_the_fields_in_july', 'In July 1863 (7 Jul) fences had disappeared from the fields south of the town and some buildings were gone or ruined (an eyewitness).', 'documented', [t1], support='partial',
          why='Four months before the dedication and a different ground; it shows only that fence loss was general south of the town.')
    R.sub('battlefield_state_on_17_nov_along_the_emmitsburg_road', 'A New-York Tribune correspondent who drove the Emmitsburg road out of Gettysburg on 17 Nov 1863 (two days before the dedication) saw rifle-pits along the whole length of the road, knapsacks, canteens, cups, bayonets, cartridge boxes, shoes, stockings and remnants of coats and vests (and numberless caps and belts) scattered through the fields and woods and along the road, wooden fences torn down and the stone ones strengthened and used as breastworks.', 'documented', [r1, r2, r3],
          why='A contemporary eyewitness, a general description of the road, not of the cemetery ground; it is the best local statement of the November state of the fences on the Emmitsburg Road: no standing wooden fences are described there, stone fences remain as breastworks.')
    R.sub('trees_marked_limbs_torn_on_the_first_day_field_17_nov', 'On the same drive, through the woods toward the grove where the fighting began on 1 Jul, the correspondent found "Trees marked, limbs and branches torn", breastworks and rifle-pits, and houses in the neighborhood scarred and torn.', 'documented', [r4], support='partial',
          why='The field of the first day (the Chambersburg Pike side), not the cemetery ground; the later words of the sentence are garbled in the OCR.')
    R.sub('broken_fences_still_visible_on_19_nov', 'Broken fences were still visible around the cemetery on 19 Nov.', 'inferred', [r3, c1], support='partial',
          why='Documented for the Emmitsburg road on 17 Nov (wooden fences torn down); for the cemetery ground itself no text: Evergreen\'s frontage had a temporary wood plank fence (CLR, a pre-battle fact); the large derivative of LOC ppmsca-32850 (the crowd of 19 Nov; viewed) shows freshly dug plots, wooden headboards and bare saplings, and no fence line can be read at that resolution (not evidence either way).')
    R.sub('scarred_trees_rifle_pits_discarded_gear', 'Cut and scarred trees, rifle pits and discarded gear were visible around the cemetery.', 'inferred', [r1, r2, r4], support='partial',
          why='Documented along the Emmitsburg road and on the first day\'s field on 17 Nov; the cemetery ground itself (Cemetery Hill) is not described, and the correspondent says only that he "visited Cemetery and Wolf Hills".')
    R.lookup('Soldiers\' National Cemetery reports, Everett 1864, Bartlett 1874, July-Nov 1863 newspapers: the ground around the cemetery on 19 Nov', 'ws9', 'only the Sentinel\'s "November mists" and the view from the platform', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov): Evening Star 19-21 Nov 1863, New-York Daily Tribune 20-21 Nov 1863: the state of the field and the fences', 'web (reachable hosts)', 'Tribune 21 Nov 1863 p.2, letter of 17 Nov: rifle-pits, gear, torn-down wooden fences along the Emmitsburg road; trees marked on the first day field; nothing on the cemetery ground', 'done')
    R.unsupported('The Blue Ridge, and broken fences, scarred trees, rifle pits and gear specifically on the cemetery ground on 19 Nov (the newspaper evidence is of the roads and fields two days earlier).')
    return R.finish('partially_supported', 'blocked_host',
        'A New-York Tribune correspondent who drove the Emmitsburg road on 17 Nov 1863 describes rifle-pits along the whole length of the road, gear scattered along it, wooden fences torn down and stone ones used as breastworks, and marked trees on the first day\'s field; nothing local describes the cemetery ground itself on 19 Nov, and the contemporary account of the day says only that the surrounding hills were dimly seen through the November mists from the stand. An eyewitness of 7 Jul says fences had disappeared from the fields south of the town.',
        register=['fence-3-EG-17'],
        blocked_host=[{'url': 'Wikipedia, Gettysburg National Cemetery / Dedication (key W-CONS)', 'what_to_read': 'Not an admissible source (Law cl.4); the primaries are the 19-20 Nov 1863 reports (New York Times, Philadelphia Inquirer, Harper\'s Weekly), not reached: the Evening Star and the New-York Daily Tribune of 19-21 Nov were read through the Library of Congress. Photographs of 19 Nov (Gardner, LOC ppmsca-32850/32851/32852; master TIFFs) should be viewed for fence lines.'}],
        product=['State schedule S-084 / WS-084-surrounding-ground: along the Emmitsburg road show rifle-pits, scattered gear and no standing wooden fences, stone fences used as breastworks (documented for 17 Nov, Tribune 21 Nov 1863); on the first day\'s field marked trees and torn limbs (documented); the same features on the cemetery ground itself only as marked plausible-procedural placements that follow the documented damage state of the nearby Evergreen and Cemetery Hill fences (fence-2 S-045); distant hills in haze (documented).'],
        changes=['The row was unsupported; a contemporary newspaper correspondent now documents the state of the Emmitsburg road and the first day\'s field two days before the dedication.'])


def S085():
    R = Row('S-085')
    s1 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'dimly seen through tbo November mists', title='Adams Sentinel, 24 Nov 1863'))
    c1 = R.cite(NPSW('snm', 'The cemetery was officially dedicated on November 19, 1863'))
    R.sub('date_late_autumn', 'The state is that of 19 Nov 1863, late autumn.', 'documented', [c1, s1], why='The date is documented; "November mists" is the newspaper\'s phrase.')
    R.sub('leaf_off_trees_and_dormant_grass', 'Trees leaf-off or nearly so, grass dormant (printed, "inferred").', 'inferred', [], support='partial',
          why='By season. A viewing of the large derivative of LOC ppmsca-32850 (crowd of 19 Nov, 2026-11-13) shows bare saplings and low dry grass at the sign post; this is a reading of a picture, not a source quotation.')
    R.lookup('local texts and viewed photograph of 19 Nov: leaf state', 'ws9, image', 'bare saplings (viewed); no text', 'done')
    R.unsupported('Leaf and grass state in words (no text).')
    return R.finish('partially_supported', 'open',
        'The state is that of 19 Nov 1863 in November mists (Sentinel); leaf-off trees and dormant grass are an inference from the season and from the photograph of the crowd (bare saplings), not a stated fact.',
        register=['fence-3-EG-18'],
        product=['State schedule S-085 / WS-085-season: keep inferred (leaf-off, dormant grass), tier-marked; no change.'])


def S086():
    R = Row('S-086')
    s1 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'tinclouded sky, giving assurance of lovely', title='Adams Sentinel, 24 Nov 1863', note='OCR "tinclouded" for "unclouded"; sentence: "Day dawned on Thursday with an unclouded sky, giving assurance of lovely weather" (the last word is lost to OCR noise).'))
    s2 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'dimly seen through tbo November mists', title='Adams Sentinel, 24 Nov 1863', note='OCR "tbo" for "the"; the sentence is the view from the platform: "In the distance the surrounding hills where, on the memorable days of July, stood the Rebel invaders, dimly seen through the November mists".'))
    tr1 = R.cite(NPSW('tribune_1121_p2', 'The eventfal morning has at last dawned. The eky is bright, and al nature has donned her best attire', note='New-York Daily Tribune, 21 Nov 1863, letter of a special correspondent dated Gettysburg, 19 Nov 1863 (the morning of the dedication). OCR "eventfal" for eventful and "eky" for sky.'))
    st1 = R.cite(NPSW('star_1119_p2', 'The weather is fine to-day', note='Evening Star (Washington), 19 Nov 1863, a dispatch from Gettysburg printed the afternoon of the dedication; the sentence continues "and the programme has been carried out successfully" (OCR garbled).'))
    st2 = R.cite(NPSW('star_1120_p2', 'morning opened bright and bean tiful', note='Evening Star (Washington), 20 Nov 1863: "Thursday morning opened bright and beautiful, and at an early hour the streets of Gettysburg were thronged with the gathering thousands"; OCR "bean tiful" for beautiful.'))
    R.sub('dawn_unclouded', 'Thursday 19 Nov dawned with an unclouded sky, giving assurance of lovely weather.', 'documented', [s1], why='A contemporary newspaper (a reprinted account of the day).')
    R.sub('bright_fine_day_three_more_contemporary_reports', 'Three further contemporary newspaper reports call the day bright or fine: the New-York Tribune\'s correspondent on the morning of 19 Nov ("The sky is bright, and all nature has donned her best attire"), the Evening Star of 19 Nov ("The weather is fine to-day") and the Evening Star of 20 Nov ("Thursday morning opened bright and beautiful").', 'documented', [tr1, st1, st2],
          why='Four contemporary statements in all with the Sentinel\'s unclouded dawn; all describe a bright, fine or unclouded morning and none says cloudy. The afternoon sky and a clearing at the prayer are not described in any of them.')
    R.sub('mists_in_the_distance', 'From the platform at the dedication the distant hills were "dimly seen through the November mists".', 'documented', [s2], why='Same account (the view from the stand); the newspaper gives no hour for the view.')
    R.sub('cloudy_default_clearing_to_sun_at_the_prayer', 'The default is cloudy clearing to sun at the prayer (conflict E-007: cloudy per W-CONS, "perfect" morning per GC-COMP).', 'open_gap', [], support='none',
          why='Four local contemporary statements describe an unclouded, bright, fine or beautiful morning, with mist in the distance from the stand later; none says "cloudy", and "sun at the prayer" is found nowhere. W-CONS (Wikipedia, "cloudy") and GC-COMP (a blog, a "perfect" morning) are not admissible; the New York Times and Philadelphia Inquirer reports of 19-20 Nov are not local and were not read. Conflict E-007 stays open: no default is chosen here.')
    R.sub('sun_position_computed', 'Sun position and shadows computed from the ephemeris for 39.82 N, 77.23 W.', 'inferred', [], support='partial', why='A computation (tools/bt/ephemeris.py of the repository), not a source claim.')
    R.lookup('Sentinel and Compiler of Nov 1863, Everett 1864, Bartlett 1874: the weather on 19 Nov', 'ws9', 'the Sentinel\'s two phrases only', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov): Evening Star 19-21 Nov 1863 and New-York Daily Tribune 20-21 Nov 1863: the weather on 19 Nov', 'web (reachable hosts), paced one request per second', 'Tribune: sky bright; Star: weather fine, morning bright and beautiful; no text says cloudy', 'done')
    R.unsupported('The weather conflict E-007 cannot be settled from local texts.')
    return R.finish('partially_supported', 'open',
        'Four contemporary newspaper statements (Adams Sentinel, New-York Tribune, Evening Star twice) call the morning of 19 Nov 1863 unclouded, bright, fine or beautiful, with mist in the distance from the stand; none says cloudy and none mentions the sun at the prayer; the plan\'s cloudy-to-sunny default has no local source and conflict E-007 stays open with no default chosen.',
        register=['fence-3-EG-18'],
        product=['State schedule S-086 / WS-086-sun-sky: keep the weather as a selectable value, no default (a bright, unclouded morning with distance haze is documented by four newspapers; cloudy-clearing has no local source and is marked unsupported; the afternoon sky is not described); sun position is computed.'],
        changes=['Three further contemporary newspaper statements (Tribune 21 Nov, Evening Star 19 and 20 Nov 1863) now document a bright, fine morning; none supports cloudy.'])


def S087():
    R = Row('S-087')
    n1 = R.cite(NPSW('snm', 'to a crowd of some 15,000 people'))
