    s1 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'the stand erected in the centre of the same was aurfmnded by at least twenty thousand citizens', title='Adams Sentinel, 24 Nov 1863: account of the dedication', note='OCR "aurfmnded" for surrounded.'))
    s2 = R.cite(LIB('ADAMS-SENTINEL-1863-11-24', 'estimated lit from twenty to forty', title='Adams Sentinel, 24 Nov 1863', note='Sentence: "The streets swarmed with people from all sections of the Union, the number variously estimated at from twenty to forty thousand"; the OCR reads "various^ estimated lit from twenty to forty thousah d", so the quotation is cut at "forty".'))
    v1 = R.cite(NPSW('tribune_1120_p1', 'occupied by civilians comprising about 15,000 people', note='New-York Daily Tribune, 20 Nov 1863, page 1, dispatch from Gettysburg dated 19 Nov: "the military were formed in line extending around the stand, the area between the stand and military being occupied by civilians comprising about 15,000 people, including men, women, and children."'))
    v2 = R.cite(NPSW('tribune_1120_p1', 'including men, women, and children'))
    v3 = R.cite(NPSW('tribune_1121_p2', 'it is estimated that at least 15,000 rsons are in town', note='New-York Daily Tribune, 21 Nov 1863, letter of a special correspondent dated Gettysburg, 19 Nov 1863 (the morning of the dedication, before the procession); OCR "rsons" for persons.'))
    v4 = R.cite(NPSW('tribune_1121_p2', 'I find some four or five thousands who, like myself. have come on in advance', note='Same letter: on reaching the cemetery grounds ahead of the procession; OCR "my- self." (a line break) read as myself.'))
    v5 = R.cite(NPSW('star_1120_p2', 'probably as large if not a larger camber ol people that ever assembled before', note='Evening Star (Washington), 20 Nov 1863: "The dedication of the Cemetery for the brave soldiers who were slain in the battle of Gettysburg induced the attendance of probably as large if not a larger number of people than ever assembled before at any one celebration in this country"; OCR "camber ol" for number of, "that" for than.'))
    v6 = R.cite(NPSW('tribune_1120_p1', 'The military escort comprised one squadron of cavalry, two batteries of ar- [tillery, and s regiment of infantry', note='OCR "ar- [tillery" for artillery and "s regiment" for a regiment (a stray bracket from the next column).'))
    v7 = R.cite(NPSW('tribune_1120_p1', 'attendance of ladies was quite large', note='OCR "attend- ance" (a line break) read as attendance.'))
    g1 = R.cite(NPSW('tribune_1121_p2', 'Governor Curtin of Pennsylvania, Governor Beymour of New-York, Ex-Governor Tod of Obie', note='New-York Daily Tribune, 21 Nov 1863, letter dated 19 Nov: those noticed on the platform "in addition to the Presidential party"; OCR "Beymour" for Seymour and "Obie" for Ohio.'))
    g2 = R.cite(NPSW('tribune_1121_p2', 'Governor Coburn of Maine, Governor Morton of Indiana, Ex-Governor Wright of Indiana, Governor Bradford of Maryland', note='Same list (the OCR reads "[G]overnor Brough of Ohio" just before this passage, "iavernor Erough of Oldo").'))
    g3 = R.cite(NPSW('tribune_1121_p2', 'Gov, Parker of New-Jersey, Ex-Gov, Dennison of Olio', note='Same list; OCR "Olio" for Ohio. Pierpont of Virginia is named in the OCR as "Ex-Governor Pirrpons of West Virginia".'))
    R.sub('range_of_estimates', 'Estimates of the crowd at the dedication range from over 10,000 (NPS article) and about 15,000 (NPS monument page) to at least 20,000 at the stand and 20,000 to 40,000 in the town (Sentinel, 24 Nov 1863); the plan prints about 15,000 to 20,000.', 'documented', [n1, n2, s1, s2],
          why='Four statements, none measured. The printed range is the middle of them; its lower and upper ends are both outside the sources read.')
    R.sub('tribune_estimates_15000_civilians_and_in_town', 'The New-York Tribune\'s dispatch of 19 Nov puts the civilians between the stand and the military at "about 15,000 people, including men, women, and children"; its correspondent\'s letter of the same morning estimates "at least 15,000 persons" in town and finds "four or five thousands" at the grounds ahead of the procession.', 'documented', [v1, v2, v3, v4],
          why='Contemporary estimates by newspaper correspondents on the day, none measured; they agree with the NPS figure of about 15,000 and sit below the Sentinel\'s 20,000.')
    R.sub('evening_star_largest_gathering', 'The Evening Star says the dedication drew "probably as large if not a larger number of people than ever assembled before at any one celebration in this country" (a qualitative statement, no number).', 'documented', [v5], support='partial',
          why='Qualitative only; it gives no count.')
    R.sub('composition_military_ladies_governors', 'The Tribune names the military escort as one squadron of cavalry, two batteries of artillery and a regiment of infantry, says "the attendance of ladies was quite large", and a correspondent lists on the platform Governors Curtin (Pennsylvania), Seymour (New York), Coburn (Maine), Morton (Indiana), Bradford (Maryland) and Parker (New Jersey), Governor Brough (of Ohio), the ex-governors Tod, Wright and Dennison, and Pierpont of Virginia.', 'documented', [v6, v7, g1, g2, g3], support='partial',
          why='Names as printed and garbled by the OCR (read from the surrounding words); neither newspaper counts the governors, so the plan\'s "six governors" is not stated; the list names six sitting governors (Curtin, Seymour, Coburn, Morton, Bradford, Parker) and others. The Tribune dispatch has the Union Glee Club and Birgfeld\'s band in the programme (not cited here).')
    R.sub('composition', 'Widows, boys at the edge (a photograph) and reporters in the crowd, and a count of "six governors" (printed).', 'open_gap', [], support='none',
          why='The newspapers give military, civilians (men, women and children), ladies and the governors present, with no count of governors; widows, boys at the edge and reporters are not found; the plan\'s keys are W-CONS (Wikipedia) and EWH (Eyewitness to History, Lincoln\'s Gettysburg Address; the host refused the connection on 2026-11-13).')
    R.lookup('local texts: crowd estimates on 19 Nov', 'ws9, NPS pages', 'four values', 'done')
    R.lookup('Library of Congress Chronicling America (www.loc.gov JSON API, tile.loc.gov): Evening Star 19-21 Nov 1863 and New-York Daily Tribune 20-21 Nov 1863: the crowd and who was present', 'web (reachable hosts), paced one request per second', 'Tribune: about 15,000 civilians, at least 15,000 in town, four or five thousand at the grounds in advance; the governors named; Star: a qualitative statement', 'done')
    R.unsupported('Widows, boys at the edge, reporters and a count of six governors; the EWH page (host refused).')
    return R.finish('corrected', 'blocked_host',
        'Crowd estimates range from over 10,000 (NPS article), about 15,000 (NPS; the New-York Tribune of 20-21 Nov 1863: about 15,000 civilians, at least 15,000 in town) to at least 20,000 round the stand and 20,000 to 40,000 in the town (Sentinel, 24 Nov 1863); the printed 15,000 to 20,000 is inside that spread. The Tribune documents military escort, civilians (men, women, children, many ladies) and the governors on the platform; widows, boys at the edge, reporters and a count of six governors have no local source.',
        register=['fence-3-EG-18'],
        blocked_host=[{'url': 'Eyewitness to History, Lincoln\'s Gettysburg Address (key EWH; the plan\'s source list names the title and prints no URL) and Wikipedia (W-CONS)', 'what_to_read': 'The statement "15,000 to 20,000" and the composition of the crowd (soldiers, civilians, widows, boys, six governors, reporters). Eyewitness to History is a compilation site: read for the primary quotations it carries, to be checked against the newspapers; the host www.eyewitnesstohistory.com refused the connection on 2026-11-13.'}],
        product=['State schedule S-087 / WS-087-crowd: carry the crowd as a range with its basis: 10,000+ (NPS article), about 15,000 (NPS page; Tribune: civilians about 15,000, at least 15,000 in town), 20,000+ at the stand (Sentinel), 20,000-40,000 in the town (Sentinel); default none; composition: military escort (one squadron of cavalry, two batteries, a regiment of infantry), civilians including many ladies, officials and the governors named (Curtin, Seymour, Coburn, Morton, Bradford, Parker, Brough, Pierpont, ex-governors Tod, Wright, Dennison); widows and boys at the edge are plausible-procedural, marked.'],
        changes=['The composition was an open gap; two newspapers of 20-21 Nov 1863 now document the military escort, civilians, ladies and the governors on the platform, and give two further estimates of about 15,000.'])


