    a1 = R.cite(NPSW('star_1120_p2', 'Gettysburg at 0# o\'clock on Wednesday eve ning', note='Evening Star (Washington), 20 Nov 1863: "The President and his suite reached Gettysburg at 6½ o\'clock on Wednesday evening and was greeted at the Depot with much enthusiasm by a large gathering of citizens, who followed him to his lodgings at the residence of David Wills, Esq." The OCR garbles the hour to "0#"; the page image (region saved at tmp/fence-3/web/chronam/star_1863-11-20_sp2_arrival3.jpg, viewed 2026-11-13) reads "6½ o\'clock".'))
    a2 = R.cite(NPSW('star_1120_p2', 'During the evening a large number of per sons continued to linger round the residence', note='Evening Star, 20 Nov 1863; the sentence continues "eager to see the President, and in hope that he would be induced to make a speech" (OCR garbled).'))
    a3 = R.cite(NPSW('star_1120_p2', 'The Band of the 5th New York Artillery ser enaded the President soon after his arrival', note='Evening Star, 20 Nov 1863; OCR "ser enaded" (a line break) read as serenaded. The band then serenaded Secretary Seward at the neighbouring house of Mr. Harper.'))
    b1 = R.cite(NPSW('tribune_1120_p1', 'After supper the President was serenaded by the excellent band of the 5th New-York Artillery', note='New-York Daily Tribune, 20 Nov 1863, page 1, dispatch from Gettysburg of 18 Nov.'))
    b2 = R.cite(NPSW('tribune_1120_p1', 'arrived here yesterday afternoon', note='Tribune dispatch of 19 Nov: "President Lincoln and the distinguished party accompanying him arrived here yesterday afternoon, and soon after the special train from Harrisburg brought Gov. Curtin and several other Governors"; the dispatch of 18 Nov in the same column says "The President\'s party arrived last evening".'))
    b3 = R.cite(NPSW('tribune_1120_p1', 'the train which conveved the Governors was de layed by a slight accident until nearly midnight', note='OCR "conveved" for conveyed; the sentence begins "The President\'s party arrived last evening, but" and ends "so that they were not able to participate in the proceedings of the night, which were of a marked character".'))
