    a4 = R.cite(NPSW('star_1120_p2', 'was greeted at the Depot with much enthusiasm by a large gathering of citizens, who followed him to his lodgings', note='Evening Star, 20 Nov 1863; the sentence ends "at the residence of David Wills, Esq." (OCR "resi dence").'))
